unconstrained fn get_logs_by_tag_oracle(
    requests: EphemeralArray<LogRetrievalRequest>,
) -> EphemeralArray<EphemeralArray<LogRetrievalResponse>> {}

/// Fetches all effects of a settled transaction by its hash.
